/**
 * Tests of js/bz.js (node tests/bz.mjs): reciprocal lattice, Wigner-Seitz cell, Bravais type and the k-path of
 * Setyawan and Curtarolo (SC).
 *
 * Reference data (REF): pymatgen 2024.8.9 KPathSetyawanCurtarolo (what HighSymmKpath(path_type="setyawan_curtarolo")
 * uses), spglib default symprec 0.01; for the cases marked tight (tri20, mclc6, mclc9, mclc56, mcl10) symprec 1e-4 and
 * angle_tolerance -1, since their random cell parameters lie within pymatgen's default 5 degree angle tolerance of a
 * higher symmetry. mclc2 and mclc4 sit on a variant boundary that pymatgen tests with exact float equality, so their
 * reference points are pymatgen's own mclc2 / mclc4 tables on its conventional cell. lowsym_cub_tet is a cubic cell
 * with a P4/mmm decoration: pymatgen follows the space group (TET), bz.js the lattice (CUB); the test checks that.
 * Per case: n name, v pymatgen variant, L lattice rows (A), s species, f fractional positions, k pymatgen's
 * fractional k-points in its primitive reciprocal basis, p path, g Gram matrix B B^T of that basis (1/A^2).
 *
 * Checks per case: variant; Gram matrix of the returned B equal to pymatgen's (relative 1e-9 of its largest entry;
 * equal Gram matrices mean the bases differ at most by an orthogonal map, so equal fractional coordinates give the
 * same points up to that rotation); every fractional k-point equal (1e-9) except MCL M_2, which pymatgen sets equal
 * to M_1 by a typo (checked against the SC paper's (1/2, eta, -nu) instead); identical path; Cartesian points = frac B
 * up to the reported fold; every point in or on wignerSeitz(B); zone volume = |det B| (relative 1e-9); Euler
 * characteristic V - E + F = 2.
 */
import { reciprocal, wignerSeitz, zoneVolume, inZone, kpath } from "../js/bz.js";

let fails = 0, n = 0;
const ok = (cond, msg) => { n++; if (!cond) { fails++; console.log("FAIL", msg); } else console.log("ok  ", msg); };
const dot = (u, v) => u[0] * v[0] + u[1] * v[1] + u[2] * v[2];
const det = m => m[0][0] * (m[1][1] * m[2][2] - m[1][2] * m[2][1]) - m[0][1] * (m[1][0] * m[2][2] - m[1][2] * m[2][0]) + m[0][2] * (m[1][0] * m[2][1] - m[1][1] * m[2][0]);
const frac2cart = (B, f) => [0, 1, 2].map(j => f[0] * B[0][j] + f[1] * B[1][j] + f[2] * B[2][j]);
/** Structure from lattice rows L (A), species and fractional positions. */
const struct = (L, s, f) => ({ lattice: L, species: s, pbc: true, pos: Float64Array.from(f.flatMap(x => frac2cart(L, x))) });
/** Rotation by angle t (rad) about the unit axis u (Rodrigues), as a 3x3 matrix acting on column vectors. */
function rotation(u, t) {
  const c = Math.cos(t), s = Math.sin(t), C = 1 - c, [x, y, z] = u;
  return [[c + x * x * C, x * y * C - z * s, x * z * C + y * s], [y * x * C + z * s, c + y * y * C, y * z * C - x * s], [z * x * C - y * s, z * y * C + x * s, c + z * z * C]];
}
const apply = (R, v) => R.map(r => dot(r, v));
/** Zone checks: volume equals |det B| (relative 1e-9) and V - E + F = 2. */
function zoneOk(B) {
  const z = wignerSeitz(B), V = Math.abs(det(B));
  return { z, vol: Math.abs(zoneVolume(z) - V) / V, euler: z.vertices.length - z.edges.length + z.faces.length };
}

