/* reciprocal lattice */
{
  const L = [[3.1, 0.2, -0.4], [0.7, 4.2, 0.3], [-1.1, 0.5, 5.3]], B = reciprocal(L);
  let e = 0;
  for (let i = 0; i < 3; i++) for (let j = 0; j < 3; j++) e = Math.max(e, Math.abs(dot(B[i], L[j]) - (i === j ? 2 * Math.PI : 0)));
  ok(e < 1e-12, `reciprocal: b_i . a_j = 2 pi delta_ij (max error ${e.toExponential(1)})`);
}
/* not periodic */
ok(kpath(null) === null && kpath({ lattice: null, pbc: false, species: ["H"], pos: new Float64Array(3) }) === null &&
  kpath({ lattice: [[5, 0, 0], [0, 5, 0], [0, 0, 5]], pbc: false, species: ["H"], pos: new Float64Array(3) }) === null, "kpath: null without a lattice or periodicity");

/* pymatgen reference cases */
for (const c of REF) {
  const r = kpath(struct(c.L, c.s, c.f), 1e-5);
  const want = c.n === "lowsym_cub_tet" ? "cub" : c.v;
  const G = r.B.map(u => r.B.map(v => dot(u, v))), gmax = Math.max(...c.g.flat().map(Math.abs));
  const gerr = Math.max(...G.flat().map((x, i) => Math.abs(x - c.g.flat()[i]))) / gmax;
  const labels = Object.keys(r.frac).sort().join(), refLabels = Object.keys(c.k).sort().join();
  let ferr = 0;
  for (const l of Object.keys(c.k)) {
    if (!r.frac[l] || (c.v === "mcl" && l === "M_2")) continue;
    ferr = Math.max(ferr, ...r.frac[l].map((x, i) => Math.abs(x - c.k[l][i])));
  }
  let perr = 0, out = [];
  const { z, vol, euler } = zoneOk(r.B);
  for (const [l, k] of Object.entries(r.points)) {
    const sh = r.folded[l] || [0, 0, 0], e = frac2cart(r.B, r.frac[l].map((x, i) => x - sh[i]));
    perr = Math.max(perr, ...k.map((x, i) => Math.abs(x - e[i])));
    if (!inZone(z, k)) out.push(l);
  }
  if (c.n === "lowsym_cub_tet") {
    ok(r.variant === "cub" && c.v === "tet" && gerr < 1e-9 && out.length === 0 && vol < 1e-9,
      `${c.n}: lattice-only CUB where pymatgen (space group P4/mmm) gives TET`);
    continue;
  }
  const m2 = c.v !== "mcl" || Math.abs(r.frac.M_2[0] - 0.5) < 1e-12 &&
    Math.abs(r.frac.M_2[1] - r.frac.H[1]) < 1e-12 && Math.abs(r.frac.M_2[2] - r.frac.H_2[2]) < 1e-12;
  ok(r.variant === want && gerr < 1e-9 && labels === refLabels && ferr < 1e-9 && JSON.stringify(r.path) === JSON.stringify(c.p) &&
    perr < 1e-12 && m2 && out.length === 0 && vol < 1e-9 && euler === 2,
    `${c.n}: ${r.type}/${r.variant} vs pymatgen ${c.v}; Gram ${gerr.toExponential(1)}, k ${ferr.toExponential(1)}, ` +
    `${Object.keys(r.points).length} points in zone${Object.keys(r.folded).length ? " (folded " + Object.keys(r.folded) + ")" : ""}, ` +
    `${z.faces.length} faces, volume ${vol.toExponential(1)}`);
}

/* TRI2a: reciprocal angles 100, 105, 90 deg; bz.js cycles the axes so that k_gamma = 90 */
{
  const ang = (u, v) => Math.acos(dot(u, v) / Math.sqrt(dot(u, u) * dot(v, v))) * 180 / Math.PI;
  const r0 = Math.PI / 180, ca = Math.cos(100 * r0), cb = Math.cos(105 * r0);
  // reciprocal rows with |b| = 1.3, 1.5, 1.9 (1/A), k_alpha = 100, k_beta = 105, k_gamma = 90, then L = 2 pi (B^-1)^T
  const Bq = [[1.3, 0, 0], [0, 1.5, 0], [1.9 * cb, 1.9 * ca, 1.9 * Math.sqrt(1 - ca * ca - cb * cb)]];
  const L = reciprocal(Bq);
  const r = kpath(struct(L, ["Si"], [[0, 0, 0]]));
  const k = [ang(r.B[1], r.B[2]), ang(r.B[0], r.B[2]), ang(r.B[0], r.B[1])];
  const { z, vol, euler } = zoneOk(r.B);
  ok(r.variant === "tri2a" && Math.abs(k[2] - 90) < 1e-9 && k[0] > 90 && k[1] > 90 && r.frac.R.join() === "0.5,0.5,0.5" &&
    Object.values(r.points).every(p => inZone(z, p)) && vol < 1e-9 && euler === 2,
    `tri2a: k angles ${k.map(x => x.toFixed(6)).join(", ")}, TRI1a table`);
}

/* the k-points turn with the structure: rotated input -> rotated points */
{
  const L = [[4.1, 0, 0], [0.9, 5.3, 0], [-1.2, 0.4, 6.2]], R = rotation([0.48, -0.6, 0.64], 1.234);
  const a = kpath(struct(L, ["Si"], [[0, 0, 0]])), b = kpath(struct(L.map(v => apply(R, v)), ["Si"], [[0, 0, 0]]));
  let e = 0;
  for (const l of Object.keys(a.points)) e = Math.max(e, ...apply(R, a.points[l]).map((x, i) => Math.abs(x - b.points[l][i])));
  ok(a.variant === b.variant && e < 1e-12, `rotated ${a.variant} cell: points rotate with it (max error ${e.toExponential(1)})`);
}

/* Wigner-Seitz cell: very oblique bases of one lattice give the same zone */
{
  let worst = 0, bad = 0, seed = 12345;
  const rnd = () => (seed = (seed * 1103515245 + 12345) % 2147483648) / 2147483648;
  for (let t = 0; t < 40; t++) {
    const B = [[1 + rnd(), 0, 0], [rnd() - 0.5, 0.8 + rnd(), 0], [rnd() - 0.5, rnd() - 0.5, 0.7 + rnd()]];
    // unimodular M with large entries: rows of M B span the same lattice
    const M = [[1, 0, 0], [0, 1, 0], [0, 0, 1]];
    for (let s = 0; s < 6; s++) { const i = Math.floor(rnd() * 3), j = (i + 1 + Math.floor(rnd() * 2)) % 3, q = Math.floor(rnd() * 7) - 3; M[i] = M[i].map((x, k) => x + q * M[j][k]); }
    const O = M.map(r => frac2cart(B, r));
    const z1 = wignerSeitz(B), z2 = wignerSeitz(O), V = Math.abs(det(B));
    const same = z1.vertices.length === z2.vertices.length && z1.vertices.every(v => z2.vertices.some(w => Math.hypot(v[0] - w[0], v[1] - w[1], v[2] - w[2]) < 1e-9));
    const e = Math.max(Math.abs(zoneVolume(z1) - V), Math.abs(zoneVolume(z2) - V)) / V;
    worst = Math.max(worst, e);
    if (!same || e > 1e-9 || z1.vertices.length - z1.edges.length + z1.faces.length !== 2 || z1.faces.length > 14) bad++;
  }
  ok(bad === 0, `wignerSeitz: 40 random lattices, bases sheared six times (factors -3..3) give the same vertices; volume error ${worst.toExponential(1)}`);
}
/* nearly cubic: a 1e-9 strain does not break the cell */
{
  const { z, vol, euler } = zoneOk([[1, 1e-9, 0], [0, 1 + 1e-9, 0], [0, 0, 1]]);
  ok(vol < 1e-9 && euler === 2, `wignerSeitz: strained cube ${z.faces.length} faces, ${z.vertices.length} vertices, volume error ${vol.toExponential(1)}`);
}

console.log(`\n${n - fails}/${n} passed`);
process.exit(fails ? 1 : 0);
